tests.pseudocode:
loader := prompt.NewLoader()
names := loader.Names()
assert len(names) > 0
for _, sub := range []string{"fix/", "impl/", "review/", "brief/", "partials/", "tools/", "refusals/", "rejections/"} {
  found := false
  for _, n := range names { if strings.HasPrefix(n, sub) { found = true; break } }
  assert found, "missing subdirectory: "+sub
}

loader := prompt.NewLoader()
names := loader.Names()
required := []string{"fix/analyse.system.md", "fix/analyse.md", "fix/implement.system.md", "fix/implement.md", "impl/survey.system.md", "impl/survey.md", "impl/task.system.md", "impl/task.md", "impl/repair.system.md", "impl/repair.md", "impl/resolve.system.md", "impl/resolve.md", "review/review.system.md", "review/review.md", "brief/fix.md", "brief/impl.md"}
for _, r := range required { assert slices.Contains(names, r), "missing: "+r }

loader := prompt.NewLoader()
names := loader.Names()
partials := []string{"partials/report.md", "partials/baseline.md", "partials/gate.md", "partials/language.md", "partials/repomap.md", "partials/instructions.md", "partials/steering.md", "partials/criteria.md", "partials/definition_of_done.md", "partials/survey.md", "partials/landed_tasks.md", "partials/previous_attempt.md", "partials/scope.md", "partials/external_apis.md", "partials/date.md", "partials/context.md", "partials/read_roots.md", "partials/scratch.md"}
for _, p := range partials { assert slices.Contains(names, p) }

loader := prompt.NewLoader()
names := loader.Names()
for _, n := range []string{"tools/execute.md", "tools/write_file.md", "tools/edit_file.md", "refusals/programs_not_allowed.md", "refusals/suite.md", "refusals/git_mutating.md", "refusals/path_outside.md", "rejections/missing_verdicts.md", "rejections/weak_evidence.md"} {
  assert slices.Contains(names, n)
}

loader := prompt.NewLoader()
validKinds := map[string]bool{"system":true, "message":true, "brief":true, "partial":true, "tool":true, "refusal":true, "rejection":true}
for _, name := range loader.Names() {
  h := loader.Header(name)
  assert h.Name != ""
  assert validKinds[h.Kind]
  assert h.View != ""
  assert h.MaxBytes > 0
}

for _, file := range []string{"codefix/prompts.go", "codeimpl/prompts.go", "internal/conform/prompt.go"} {
  src := readFile(file)
  for _, sym := range removedSymbols {
    assert !containsDeclaration(src, sym), "%s still declares %s", file, sym
  }
}

dirs := []string{"internal/engine", "codefix", "codeimpl", "internal/conform"}
for _, dir := range dirs {
  for _, file := range goFiles(dir) {
    if isTestFile(file) { continue }
    literals := extractStringLiterals(file)
    for _, lit := range literals {
      if len(lit) > 120 && containsKeyword(lit) && !isException(lit) {
        t.Errorf("%s contains model-facing prose: %q", file, lit[:80])
      }
    }
  }
}

loader := prompt.NewLoader()
for _, name := range loader.Names() {
  h := loader.Header(name)
  if !h.Stable { continue }
  view := loadFixtureView(name)
  out1, _ := loader.Render(name, view)
  out2, _ := loader.Render(name, view)
  assert out1 == out2, "stable template %s not byte-identical", name
}

loader := prompt.NewLoader()
names := loader.Names()
nameSet := toSet(names)
for _, name := range names {
  src := loader.Source(name) // or read from embedded FS
  refs := extractTemplateRefs(src) // find {{template "..." .}} patterns
  for _, ref := range refs {
    assert nameSet[ref], "template %s references non-existent partial %s", name, ref
  }
}

run := toolio.NewRun("fix", "v1")
WritePrompts("/dev/null", "fix", "ts", "sid", "analyse", "", 0, "sys", "usr", nil)
warnings := run.Warnings()
found := false
for _, w := range warnings {
  if w.Code == toolio.WarnPromptsNotWritten && w.Severity == "low" { found = true }
}
assert found

loader := prompt.NewLoader()
for _, dangerous := range generateDangerousStrings() {
  view := struct{ Text string }{Text: dangerous}
  out := renderTestTemplate(loader, `{{.Text}}`, view)
  assert strings.Contains(out, dangerous)
}
